// CSD_RATIONALE_BEGIN
// This CSD strategy processes inputs from the gsm_symbolic dataset to solve math word problems step by step.
// It writes each arithmetic computation inside << >> delimiters.
// The strategy uses constrained windows to ensure valid arithmetic expressions are generated.
// The model generates unconstrained tokens until it encounters "<<", then enters a constrained window.
// Inside the constrained window, the model generates tokens under grammar constraints until it encounters ">>".
// The strategy uses TemperatureConstrainedStep to control the generation process.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
    }
